@participant2 
IMO, this should be backend agnostic. The split method should not use tf ops with torch backend, instead it should have backend specific splitting method.

https://github.com/keras-team/keras-hub/issues/2128

Would it make sense to construct an factory or registry that dynamically constructs an object based on `backend.backend()`, and within each object the specific imports are locally performed? Something (very simplified) to the effect of:

```python

from abc import ABC, abstractmethod
from typing import Dict, Callable
from copy import copy
from keras.src import backend


class DatasetHandler(ABC):
    @participant7
    def split_dataset(self, dataset, left_size=None, right_size=None, shuffle=False, seed=None):
        ...


class DatasetHandlerRegistry:
    dataset_handlers: Dict[str, DatasetHandler] = {}

    @participant8
    def register(cls, key: str):
        def decorator(dataset_handler_class: Callable[[], DatasetHandler]) -> Callable[[], DatasetHandler]:
            cls.dataset_handlers[key] = dataset_handler_class()
            return dataset_handler_class

        return decorator

    @participant8
    def get_handler(cls, key: str) -> DatasetHandler:
        return copy(cls.dataset_handlers[key])


@participant9.register("tensorflow")
class TensorflowDatasetHandler(DatasetHandler):
    def split_dataset(self, dataset, left_size=None, right_size=None, shuffle=False, seed=None):
        import tensorflow as tf
        # do current tensorflow stuff here
        pass


@participant9.register("torch")
class TorchDatasetHandler(DatasetHandler):
    def split_dataset(self, dataset, left_size=None, right_size=None, shuffle=False, seed=None):
        import torch
        # do torch stuff here
        pass


def split_dataset(dataset, left_size=None, right_size=None, shuffle=False, seed=None):
    keras_backend = backend.backend()
    dataset_handler = DatasetHandlerRegistry.get_handler(keras_backend)
    return dataset_handler.split_dataset(dataset, left_size, right_size, shuffle, seed)

```
